import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class StudyExternalGenotypeQcTest {
    @TempDir Path root;
    private Context context(String name,Map<String,Object> overrides,boolean imputed)throws Exception {
        var policy=new LinkedHashMap<String,Object>(Map.of("source","supplied","pca_source","supplied"));policy.putAll(overrides);
        var base=StudyGenotypeQcFixtures.context(root,name,policy,Map.of(),Map.of(),imputed,true);var expected=DelimitedData.readResult(StudyGenotypeQcFixtures.resource("expected-pcs.tsv"));
        var calls=DelimitedData.readResult(StudyGenotypeQcFixtures.resource("hard-calls.tsv"));var rows=new ArrayList<String[]>();for(String[] row:expected.rows()){boolean basis=Boolean.parseBoolean(row[expected.column("pca_basis")]);int column=calls.column(row[0]);double rate=calls.rows().stream().filter(v->!v[column].equals("NA")).count()/(double)calls.rows().size();rows.add(new String[]{row[0],"complete",basis?"keep":"exclude",basis?"":"relatedness",Double.toString(rate),Boolean.toString(basis)});}
        java.util.Collections.reverse(rows);FollowupSupport.table(base.project().resolve("external-samples.tsv"),List.of("sample_id","status","decision","reason","observed_call_rate","pca_basis"),rows);Files.copy(StudyGenotypeQcFixtures.resource("expected-pcs.tsv"),base.project().resolve("external-pcs.tsv"));
        var report=new LinkedHashMap<String,Object>();report.put("schema_version",1);report.put("analysis_id","PRIVATE_EXTERNAL_METHOD_SENTINEL");report.put("dataset_id","a");report.put("analysis_matrix_sha256",FollowupSupport.hash(base.project().resolve("main.vcf")));report.put("genome_build","GRCh38");report.put("status","complete");report.put("sample_universe","complete");
        report.put("sample_qc",Map.of("status","complete","software","synthetic-reference","software_version","1","call_rate_scope","observed_autosomal_hard_calls","minimum_call_rate",.98,"samples",64));
        var kin=new LinkedHashMap<String,Object>();kin.put("status","complete");kin.put("software","synthetic-NumPy-reference");kin.put("software_version","2.4.4");kin.put("estimator","KING_between_family");kin.put("support","Independent synthetic reference counts, not actual cohort QC");kin.put("kinship_threshold",Math.pow(2,-3.5));kin.put("action","exclude");kin.put("minimum_shared_markers",2000);kin.put("minimum_pair_heterozygotes",100);kin.put("evaluated_samples",64);kin.put("evaluated_pairs",2016);kin.put("related_pairs",4);kin.put("unresolved_pairs",0);kin.put("independent_basis_complete",true);kin.put("retained_population_compatible",true);report.put("relatedness",kin);
        report.put("pca",Map.of("status","complete","software","NumPy","software_version","2.4.4","basis","Synthetic original 62-member unrelated basis","basis_samples",62,"columns",List.of("GPC1","GPC2")));
        report.put("file_sha256",Map.of("sample_qc_samples",FollowupSupport.hash(base.project().resolve("external-samples.tsv")),"sample_qc_pcs",FollowupSupport.hash(base.project().resolve("external-pcs.tsv"))));write(base.project().resolve("external-qc.yaml"),report);
        var study=new LinkedHashMap<>(base.study());var d=new LinkedHashMap<>(map(list(study.get("datasets")).get(0)));var files=new LinkedHashMap<>(map(d.get("files")));files.put("sample_qc_report","external-qc.yaml");files.put("sample_qc_samples","external-samples.tsv");files.put("sample_qc_pcs","external-pcs.tsv");d.put("files",files);study.put("datasets",List.of(d));return new Context(base.project(),base.outputDirectory(),base.operation(),study,base.plan(),base.dependencyDirectories());
    }
    private static Map<String,Object> qc(Result r){return map(r.details().get("genotype_sample_qc"));}
    private static void change(Context c,String section,String key,Object value)throws Exception {Path path=c.project().resolve("external-qc.yaml");var report=new LinkedHashMap<>(StudyYaml.loadArtifact(path));if(section.isEmpty())report.put(key,value);else {var sub=new LinkedHashMap<>(map(report.get(section)));sub.put(key,value);report.put(section,sub);}write(path,report);}
    private static void reseal(Context c,String role,String filename)throws Exception {change(c,"file_sha256",role,FollowupSupport.hash(c.project().resolve(filename)));}
    @Test void completeExternalQcAndPcsAreReusedWithoutNativeSourcePairOrPcaWork()throws Exception {
        var c=context("complete",Map.of("maximum_samples",3,"maximum_source_cells",1,"maximum_pca_work",1),false);var result=new StudyPrefitQc().execute(c);assertEquals(State.COMPLETE,result.state(),result.details().toString());assertEquals(62,result.details().get("analysis_samples"));assertEquals(2,map(result.details().get("excluded_by_reason")).get("external_qc_relatedness"));assertEquals("externally_produced",qc(result).get("execution_origin"));assertEquals(false,qc(result).get("native_relatedness_computed"));assertEquals(false,qc(result).get("pca_computed"));assertEquals("externally_supplied",qc(result).get("pca_status"));assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/pairs.tsv")));assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/marker-inventory.tsv")));assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/pc-weights.tsv")));assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/initial-call-rates.tsv")));
        var selected=DelimitedData.read(c.outputDirectory().resolve("analysis-phenotype.tsv"));var expected=DelimitedData.readResult(StudyGenotypeQcFixtures.resource("expected-pcs.tsv"));for(String[] row:selected.rows()){var ref=expected.rows().stream().filter(r->r[0].equals(row[0])).findFirst().orElseThrow();assertEquals(Double.parseDouble(ref[expected.column("GPC1")]),Double.parseDouble(row[selected.column("GPC1")]),0);}
    }
    @Test void rawPhenotypeSubsettingDoesNotRefitOrRecenterSourcePcs()throws Exception {
        var c=context("phenotype-subset",Map.of(),false);var lines=Files.readAllLines(c.project().resolve("phenotype.tsv"));String[] row=lines.get(lines.size()-1).split("\t",-1);row[1]="NA";lines.set(lines.size()-1,String.join("\t",row));Files.write(c.project().resolve("phenotype.tsv"),lines);var result=new StudyPrefitQc().execute(c);assertEquals(State.COMPLETE,result.state(),result.details().toString());assertEquals(61,result.details().get("analysis_samples"));assertEquals(62L,qc(result).get("external_pca_basis_samples"));assertEquals(false,qc(result).get("pca_computed"));
    }
    @Test void onlyMissingNativePcaRunsOnTheAcceptedExternalBasis()throws Exception {
        var c=context("missing-pca",Map.of("pca_source","native","maximum_pair_word_work",1),false);change(c,"pca","status","partial");var result=new StudyPrefitQc().execute(c);assertEquals(State.COMPLETE,result.state(),result.details().toString());assertEquals("mixed_external_qc_native_pca",qc(result).get("execution_origin"));assertEquals(true,qc(result).get("pca_computed"));assertEquals(false,qc(result).get("native_relatedness_computed"));assertEquals(62,qc(result).get("unrelated_basis_samples"));assertTrue(Files.exists(c.outputDirectory().resolve("genotype-qc/pc-weights.tsv")));assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/pairs.tsv")));assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/initial-call-rates.tsv")));assertTrue(text(map(qc(result).get("method_report")).get("method")).contains("externally completed"));
    }
    @Test void partialExternalPcaPreservesAcceptedQcExclusionsButDoesNotApproveRows()throws Exception {
        var c=context("partial-pca",Map.of(),false);change(c,"pca","status","partial");var result=new StudyPrefitQc().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertEquals(true,qc(result).get("external_sample_qc_complete"));assertEquals(0,result.details().get("analysis_samples"));assertEquals(62,result.details().get("candidate_samples_for_diagnostics"));assertEquals(2,DelimitedData.readResult(c.outputDirectory().resolve("sample-exclusions.tsv")).rows().size());assertFalse(Files.exists(c.outputDirectory().resolve("analysis-phenotype.tsv")));assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/marker-inventory.tsv")));
    }
    @Test void partialSourceQcCannotSelectACompletePopulation()throws Exception {
        var c=context("partial-qc",Map.of(),false);change(c,"sample_qc","status","partial");var result=new StudyPrefitQc().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertEquals(false,qc(result).get("external_sample_qc_complete"));assertEquals(64,result.details().get("candidate_samples_for_diagnostics"));assertFalse(Files.exists(c.outputDirectory().resolve("analysis-phenotype.tsv")));
    }
    @Test void changedSampleAndMatrixHashesAndWrongPairScopeHoldWithoutSilentIntersection()throws Exception {
        for(String mode:List.of("matrix","data","pairs","threshold")){var c=context("wrong-"+mode,Map.of(),false);switch(mode){case "matrix"->change(c,"","analysis_matrix_sha256","0".repeat(64));case "data"->Files.writeString(c.project().resolve("external-samples.tsv"),Files.readString(c.project().resolve("external-samples.tsv")).replace("S63","OUTSIDE"));case "pairs"->change(c,"relatedness","evaluated_pairs",2015);case "threshold"->change(c,"relatedness","kinship_threshold",.1);default->throw new AssertionError();}var result=new StudyPrefitQc().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state(),mode);assertEquals(0,result.details().get("analysis_samples"));assertFalse(Files.exists(c.outputDirectory().resolve("analysis-phenotype.tsv")));assertTrue(Files.exists(c.outputDirectory().resolve("genotype-qc/external/import-errors.txt")));}
    }
    @Test void declaredImputationStillRequiresRealMainMatrixQualityAnnotations()throws Exception {
        var c=context("imputed",Map.of(),true);Path path=c.project().resolve("main.vcf");Files.writeString(path,Files.readString(path).replace("R2=0.99","."));change(c,"","analysis_matrix_sha256",FollowupSupport.hash(path));var result=new StudyPrefitQc().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertEquals("absent",map(result.details().get("imputation_quality_availability")).get("status"));assertEquals(4L,result.details().get("variants_without_imputation_quality"));assertEquals(0L,result.details().get("examined_genotype_variants"));assertFalse(Files.exists(c.outputDirectory().resolve("analysis-phenotype.tsv")));
    }
    @Test void currentModelRequirementsAreNotReplacedByExternalClaims()throws Exception {
        var c=context("model",Map.of("relatedness_action","model"),false);change(c,"relatedness","action","model");Path path=c.project().resolve("external-samples.tsv");Files.writeString(path,Files.readString(path).replace("\texclude\trelatedness\t","\tkeep\t\t"));reseal(c,"sample_qc_samples","external-samples.tsv");var result=new StudyPrefitQc().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertTrue(qc(result).toString().contains("GRM model"));
    }
    @Test void linearImportBoundsAreDistinctFromNativeQuadraticWorkBounds()throws Exception {
        var c=context("import-bound",Map.of("maximum_import_samples",32),false);var result=new StudyPrefitQc().execute(c);assertEquals(State.WAITING_FOR_INPUT,result.state());assertEquals(false,qc(result).get("external_sample_qc_complete"));assertFalse(Files.exists(c.outputDirectory().resolve("analysis-phenotype.tsv")));
    }
    @Test void diagnosticOnlyImportedPcsDoNotSilentlyEnterRegressionCovariates()throws Exception {
        var c=context("diagnostic",Map.of("include_pcs",false),false);var result=new StudyPrefitQc().execute(c);assertEquals(State.COMPLETE,result.state(),result.details().toString());assertTrue(Files.exists(c.outputDirectory().resolve("genotype-qc/pcs.tsv")));assertFalse(DelimitedData.read(c.outputDirectory().resolve("analysis-phenotype.tsv")).header().contains("GPC1"));
    }
    @Test void participantDetailsAndExternalMethodNotesAreExcludedFromFindingContext()throws Exception {
        var c=context("privacy",Map.of(),false);var result=new StudyPrefitQc().execute(c);assertEquals(State.COMPLETE,result.state());var hashes=new LinkedHashMap<String,Object>();for(String output:result.outputs())hashes.put(output,FollowupSupport.hash(c.outputDirectory().resolve(output)));write(c.outputDirectory().resolve("manifest.yaml"),Map.of("operation_id","qc","operation_type","participant_qc","hypothesis","H","state","complete","details",result.details(),"output_sha256",hashes));Path primary=Files.createDirectories(c.project().resolve("primary/standard-results"));Files.writeString(primary.resolve("a.tsv"),"feature_id\tbeta\tse\tp_value\nassoc1\t1\t.1\t1e-12\n");StudyTestSources.seal(primary.getParent(),"validate_harmonize","primary","H");var inv=new Context(c.project(),Files.createDirectories(c.project().resolve("inventory")),Map.of("type","finding_inventory","hypothesis","H","datasets",List.of("a")),c.study(),Map.of(),Map.of("qc",c.outputDirectory(),"primary",primary.getParent()));new StudyFindingInventory().execute(inv);String body=Files.readString(inv.outputDirectory().resolve("finding-inventory.jsonl"));assertFalse(body.contains("S00"));assertFalse(body.contains("PRIVATE_EXTERNAL_METHOD_SENTINEL"));assertTrue(body.contains("externally_produced"));assertTrue(body.contains("not independently reproduced"));
    }
    @Test void automaticMethodsDoNotCopyPrivateSourceProvenanceOrLimitations()throws Exception {
        var c=context("methods-privacy",Map.of(),false);change(c,"","limitations",List.of("PRIVATE_SOURCE_LIMITATION_SENTINEL; participant S00"));change(c,"","provenance",Map.of("private_notes","PRIVATE_SOURCE_PROVENANCE_SENTINEL; participant S00"));var result=new StudyPrefitQc().execute(c);assertEquals(State.COMPLETE,result.state(),result.details().toString());assertTrue(qc(result).toString().contains("PRIVATE_SOURCE_PROVENANCE_SENTINEL"));String method=map(result.details().get("method_report")).toString();assertFalse(method.contains("PRIVATE_"));assertFalse(method.contains("S00"));assertTrue(method.contains("metadata_review_required"));
    }
    @Test void missingAndDuplicatePcRowsAreDetectedEvenWithMatchingSourceHashes()throws Exception {
        for(String mode:List.of("missing","duplicate")){var c=context("pc-"+mode,Map.of(),false);Path pcs=c.project().resolve("external-pcs.tsv");var lines=Files.readAllLines(pcs);if(mode.equals("missing"))lines.remove(lines.size()-1);else lines.add(lines.get(1));Files.write(pcs,lines);reseal(c,"sample_qc_pcs","external-pcs.tsv");var r=new StudyPrefitQc().execute(c);assertEquals(State.WAITING_FOR_INPUT,r.state());assertEquals(true,qc(r).get("external_sample_qc_complete"));assertEquals(2,DelimitedData.readResult(c.outputDirectory().resolve("sample-exclusions.tsv")).rows().size());assertFalse(Files.exists(c.outputDirectory().resolve("analysis-phenotype.tsv")));}
    }
    @Test void completeExternalQcDoesNotRequirePcaWhenNoneWasRequested()throws Exception {
        var c=context("no-pca",Map.of("pca_components",0,"include_pcs",false),false);change(c,"pca","status","partial");var result=new StudyPrefitQc().execute(c);assertEquals(State.COMPLETE,result.state(),result.details().toString());assertEquals("not_requested",qc(result).get("pca_status"));assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/pcs.tsv")));assertEquals(62,result.details().get("analysis_samples"));
    }
    @Test void eachCohortCanChooseItsOwnExplicitSourceWithoutChangingOthers()throws Exception {
        var p=org.jlinalg.study.StudyGenotypeSampleQcPolicy.resolve(Map.of("genome_build","GRCh38","rationale","Synthetic per-cohort reuse","dataset_sources",Map.of("a",Map.of("source","supplied"),"b",Map.of("source","supplied","pca_source","native"))));assertEquals("supplied",org.jlinalg.study.StudyGenotypeSampleQcPolicy.forDataset(p,"a").get("pca_source"));assertEquals("native",org.jlinalg.study.StudyGenotypeSampleQcPolicy.forDataset(p,"b").get("pca_source"));assertEquals("native",org.jlinalg.study.StudyGenotypeSampleQcPolicy.forDataset(p,"c").get("source"));var invalid=new LinkedHashMap<String,Object>();invalid.put("source",null);assertThrows(IllegalArgumentException.class,()->org.jlinalg.study.StudyGenotypeSampleQcPolicy.resolve(invalid));
    }
    @Test void sourcePcsMayComeFromAnExplicitLargerExternalReferenceBasis()throws Exception {
        for(boolean complete:List.of(true,false)){var c=context("reference-"+complete,Map.of(),false);change(c,"pca","basis_samples",128);change(c,"pca","basis_scope","external_reference");change(c,"pca","basis","Synthetic structural-scope control; source reference fitting was not reproduced");if(complete){change(c,"pca","reference_id","PRIVATE_REFERENCE_SCOPE_SENTINEL");change(c,"pca","reference_sha256",FollowupSupport.hash(StudyGenotypeQcFixtures.resource("expected-weights.tsv")));}var r=new StudyPrefitQc().execute(c);assertEquals(complete?State.COMPLETE:State.WAITING_FOR_INPUT,r.state(),r.details().toString());if(complete){assertEquals("external_reference",qc(r).get("external_pca_basis_scope"));assertEquals(128L,qc(r).get("external_pca_basis_samples"));assertEquals(false,qc(r).get("pca_computed"));}}
    }
    @Test void anUnusedIndependentBasisIsNotARequirementForCompletedSourcePcs()throws Exception {
        for(boolean nativePca:List.of(false,true)){var c=context("basis-needed-"+nativePca,Map.of("pca_source",nativePca?"native":"supplied"),false);change(c,"relatedness","independent_basis_complete",false);var r=new StudyPrefitQc().execute(c);assertEquals(nativePca?State.WAITING_FOR_INPUT:State.COMPLETE,r.state(),r.details().toString());assertEquals(true,qc(r).get("external_sample_qc_complete"));assertEquals(2,DelimitedData.readResult(c.outputDirectory().resolve("sample-exclusions.tsv")).rows().size());assertEquals(62,r.details().get("candidate_samples_for_diagnostics"));if(nativePca)assertFalse(Files.exists(c.outputDirectory().resolve("genotype-qc/marker-inventory.tsv")));}
    }
    @Test void qcOnlyRelatedModelReuseDoesNotRequireAnUnusedBasisRoster()throws Exception {
        var c=context("no-basis-model",Map.of("relatedness_action","model","pca_components",0,"include_pcs",false),false);change(c,"relatedness","action","model");change(c,"relatedness","independent_basis_complete",false);Path path=c.project().resolve("external-samples.tsv");var data=DelimitedData.readResult(path);var header=new ArrayList<>(data.header());int basis=header.indexOf("pca_basis");header.remove(basis);var rows=new ArrayList<String[]>();for(String[] row:data.rows()){var cells=new ArrayList<>(List.of(row));cells.remove(basis);if(cells.get(2).equals("exclude")){cells.set(2,"keep");cells.set(3,"");}rows.add(cells.toArray(String[]::new));}FollowupSupport.table(path,header,rows);reseal(c,"sample_qc_samples","external-samples.tsv");
        var study=new LinkedHashMap<>(c.study());var dataset=new LinkedHashMap<>(map(list(study.get("datasets")).get(0)));var files=new LinkedHashMap<>(map(dataset.get("files")));files.put("grm","grm.tsv");dataset.put("files",files);study.put("datasets",List.of(dataset));Files.writeString(c.project().resolve("grm.tsv"),"QC tests the declared route only; downstream validates covariance and fit.\n");var h=new LinkedHashMap<>(map(list(study.get("hypotheses")).get(0)));var a=new LinkedHashMap<>(map(h.get("analysis")));a.put("association",Map.of("model","lmm"));a.put("goals",List.of("impact_assessment"));h.put("analysis",a);study.put("hypotheses",List.of(h));var r=new StudyPrefitQc().execute(new Context(c.project(),c.outputDirectory(),c.operation(),study,c.plan(),c.dependencyDirectories()));assertEquals(State.COMPLETE,r.state(),r.details().toString());assertEquals(64,r.details().get("analysis_samples"));assertEquals(false,qc(r).get("external_basis_membership_present"));assertFalse(qc(r).containsKey("external_basis_samples"));assertEquals("not_requested",qc(r).get("pca_status"));
    }
}
